	/* add in old sum, and carry.. */
	result += (__force u32)sum;
	/* 32+c bits -> 32 bits */
	result = (result & 0xffffffff) + (result >> 32);
	return (__force __wsum)result;
}

static inline __wsum csum_sub(__wsum csum, __wsum addend) /* <=== csum_sub */ 
{
	return csum_add(csum, ~addend);
}

static inline unsigned short from32to16(unsigned int x) /* <=== from32to16 */ 
{
	/* 32 bits --> 16 bits + carry */
	x = (x & 0xffff) + (x >> 16);
	/* 16 bits + carry --> 16 bits including carry */
	x = (x & 0xffff) + (x >> 16);
	return (unsigned short)x;
}

static inline unsigned short from32to16(unsigned long x) /* <=== from32to16 */ 
{
	/* add up 16-bit and 16-bit for 16+c bit */
	x = (x & 0xffff) + (x >> 16);
	/* add up carry.. */
	x = (x & 0xffff) + (x >> 16);
	return x;
}

__wsum csum_partial(const void *buff, int len, __wsum sum) /* <=== csum_partial */ 
{
	unsigned int result = do_csum(buff, len);
	addc(result, sum);
	return (__force __wsum)from32to16(result);
}

static inline __wsum csum_add(__wsum csum, __wsum addend) /* <=== csum_add */ 
{
	u32 res = (__force u32)csum;
	res += (__force u32)addend;
	return (__force __wsum)(res + (res < (__force u32)addend));
}

static inline unsigned long /* <=== copy_to_user */ 
